"""Independent dot-product exercises, source pp.890–892."""
from early_helpers import Book
import sympy as S,math
b=Book('12.3',[890,891,892]);proofs=[]
def m(x):return r'\('+x+r'\)'
def v(a):return r'\langle '+','.join(S.latex(S.sympify(x))for x in a)+r'\rangle'
def add(n,st,se,ks,es,an,ae=None,parts=[],ck='원래 조건과 계산 결과를 대조했다.',ce='The result was checked against the original conditions.'):
 b.add(n,890 if n<=7 else 891 if n<=44 else 892,('내적·각도·정사영','Dot products, angles and projections'),(st,se),list(zip(ks,es)),(an,an if ae is None else ae),parts,check=(ck,ce));b.E[n]['conceptHref']='../../calc1/index.html'
def exact(n,a,c,task='dot'):
 av=S.Matrix(a);bv=S.Matrix(c);dot=av.dot(bv);den=av.norm()*bv.norm()
 if task=='dot':ans=m(r'a\cdot b='+S.latex(dot));ks=[m(r'a\cdot b='+ '+'.join('('+S.latex(x)+')('+S.latex(y)+')'for x,y in zip(av,bv)))];es=ks;ko='내적을 구하라: ';en='Find the dot product: '
 else:
  co=S.simplify(dot/den);ang=math.degrees(math.acos(float(co)));ans=m(r'\theta=\arccos\left('+S.latex(co)+fr'\right)\approx{ang:.0f}^\circ');ks=[m(r'a\cdot b='+S.latex(dot)+r',\quad|a||b|='+S.latex(den)),m(r'\cos\theta=\frac{a\cdot b}{|a||b|}')];es=ks;ko='사이각의 정확한 식과 가장 가까운 정수 도를 구하라: ';en='Find the exact angle and round to the nearest degree: '
 add(n,ko+m('a='+v(a)+r',\ b='+v(c)),en+m('a='+v(a)+r',\ b='+v(c)),ks,es,ans,ck='성분별 곱의 합으로 내적을 독립 계산했다.',ce='The dot product was independently computed as a sum of coordinate products.')
add(1,'(a)(a·b)·c,(b)(a·b)c,(c)|a|(b·c),(d)a·(b+c),(e)a·b+c,(f)|a|·(b+c)의 정의 가능 여부를 설명하라.','Determine which expressions are defined: (a)(a·b)·c,(b)(a·b)c,(c)|a|(b·c),(d)a·(b+c),(e)a·b+c,(f)|a|·(b+c).',['내적은 두 벡터에서 스칼라를 만든다. 스칼라배는 벡터에 스칼라를 곱하는 연산이다.','(a),(f)는 스칼라와 벡터를 내적하려 하고 (e)는 서로 다른 종류를 더한다.'],['A dot product takes two vectors and returns a scalar. Scalar multiplication multiplies a vector by a scalar.','(a),(f) try to dot a scalar with a vector; (e) adds unlike types.'],'정의됨: (b)벡터,(c)스칼라,(d)스칼라. 정의되지 않음: (a),(e),(f).','Defined:(b)vector,(c)scalar,(d)scalar. Undefined:(a),(e),(f).',list('abcdef'),ck='곱셈과 내적 기호를 구분해야 한다.',ce='Distinguish scalar multiplication from the dot product.')
p,q=S.symbols('p q',real=True)
for n,a,c in [(2,(5,-2),(3,4)),(3,(S.Rational(3,2),S.Rational(2,5)),(-4,6)),(4,(6,-2,3),(2,5,-1)),(5,(4,1,S.Rational(1,4)),(6,-3,-8)),(6,(p,-p,2*p),(2*q,q,-q)),(7,(2,1,0),(1,-1,1)),(8,(3,2,-1),(4,0,5))]:exact(n,a,c)
for n,aa,bb,theta in [(9,7,4,S.pi/6),(10,80,50,3*S.pi/4)]:
 val=aa*bb*S.cos(theta);add(n,m(fr'|a|={aa},|b|={bb},\theta='+S.latex(theta))+'일 때 내적을 구하라.','Find the dot product given '+m(fr'|a|={aa},|b|={bb},\theta='+S.latex(theta))+'.',[m(r'a\cdot b=|a||b|\cos\theta')],[m(r'a\cdot b=|a||b|\cos\theta')],m(r'a\cdot b='+S.latex(val)),ck='예각이면 양수, 둔각이면 음수이다.',ce='An acute angle gives a positive product and an obtuse one a negative product.')
add(11,'정삼각형 꼭대기에서 왼쪽·오른쪽 꼭짓점으로 향하는 벡터를 u,v, 왼쪽에서 오른쪽 밑변을 w라 하자. |u|=1일 때 u·v,u·w를 구하라.','In an equilateral triangle, u,v run from the top to the left/right bottom vertices and w runs left to right. Given |u|=1, find u·v,u·w.',[m(r'|u|=|v|=|w|=1,\quad \angle(u,v)=60^\circ,\quad\angle(u,w)=120^\circ')],[m(r'|u|=|v|=|w|=1,\quad \angle(u,v)=60^\circ,\quad\angle(u,w)=120^\circ')],m(r'u\cdot v=1/2,\quad u\cdot w=-1/2'),ck='w=v−u이므로 u·w=u·v−1=−1/2이다.',ce='Since w=v−u, u·w=u·v−1=−1/2.')
add(12,'단위 정사각형의 왼쪽 위에서 오른쪽 위·왼쪽 아래·중심으로 향하는 벡터를 각각 u,w,v라 하자. u·v,u·w를 구하라.','In a unit square, vectors u,w,v go from the upper-left corner to the upper-right, lower-left, and center. Find u·v,u·w.',[m(r'u=\langle1,0\rangle,\ w=\langle0,-1\rangle,\ v=\langle1/2,-1/2\rangle')],[m(r'u=\langle1,0\rangle,\ w=\langle0,-1\rangle,\ v=\langle1/2,-1/2\rangle')],m(r'u\cdot v=1/2,\quad u\cdot w=0'),ck='v=(u+w)/2이고 u,w는 수직이다.',ce='v=(u+w)/2 and u,w are perpendicular.')
add(13,'표준기저i,j,k에 대해 (a)서로 다른 두 기저의 내적은0,(b)자기 자신과의 내적은1임을 보여라.','For standard basis vectors i,j,k, prove(a)distinct basis vectors have dot product0 and(b)each self-product equals1.',[m(r'i=\langle1,0,0\rangle,\ j=\langle0,1,0\rangle,\ k=\langle0,0,1\rangle'),'서로 다른 벡터의 대응 성분 곱은 모두0이다. 같은 벡터는1²인 항 하나를 갖는다.'],[m(r'i=\langle1,0,0\rangle,\ j=\langle0,1,0\rangle,\ k=\langle0,0,1\rangle'),'All coordinate products vanish for distinct basis vectors; a self-product has one term1².'],m(r'i\cdot j=j\cdot k=k\cdot i=0,\quad i\cdot i=j\cdot j=k\cdot k=1'),parts=list('ab'))
add(14,'판매량A=(a,b,c)와 단가P=(4,2.5,1)달러가 햄버거·핫도그·물에 해당한다. A·P의 의미를 설명하라.','Quantities A=(a,b,c) and prices P=(4,2.5,1)dollars correspond to hamburgers, hot dogs, and water. Interpret A·P.',[m(r'A\cdot P=4a+2.5b+c')],[m(r'A\cdot P=4a+2.5b+c')],'그날의 총 매출액(달러).','Total sales revenue for the day, in dollars.',ck='각 항은 수량×달러/개이므로 달러 단위이다.',ce='Each quantity times dollars per item contributes dollars.')
for n,a,c in [(15,(5,1),(3,2)),(16,(1,-3),(-3,4)),(17,(1,-4,1),(0,2,-2)),(18,(-1,3,4),(5,2,1)),(19,(1,-4,1),(-3,1,5)),(20,(8,-1,4),(0,4,2))]:exact(n,a,c,'angle')
for n,names,pts in [(21,'PQR',[(2,0),(0,3),(3,4)]),(22,'ABC',[(1,0,-1),(3,-2,0),(1,3,3)])]:
 ks=[];ans=[]
 for i in range(3):
  a=S.Matrix(pts[(i+1)%3])-S.Matrix(pts[i]);c=S.Matrix(pts[(i+2)%3])-S.Matrix(pts[i]);co=S.simplify(a.dot(c)/(a.norm()*c.norm()));deg=math.degrees(math.acos(float(co)));ks.append(m(r'\cos\angle '+names[i]+'='+S.latex(co)));ans.append(fr'\angle {names[i]}\approx{deg:.0f}^\circ')
 add(n,'삼각형 '+m(','.join(names[i]+'='+str(pts[i])for i in range(3)))+'의 세 각을 정수 도로 구하라.','Find the three angles, to the nearest degree, for '+m(','.join(names[i]+'='+str(pts[i])for i in range(3)))+'.',ks,ks,m(r',\ '.join(ans)),ck='반올림 전의 각도 합은180°이다.',ce='The unrounded angles sum to180°.')
cc=S.symbols('c',real=True)
for n,pairs in [(23,[((9,3),(-2,6)),((4,5,-2),(3,-1,5)),((-8,12,4),(6,-9,-3)),((3,-1,3),(5,9,-2))]),(24,[((-5,4,-2),(3,4,-1)),((9,-6,3),(-6,4,-2)),((cc,cc,cc),(cc,0,-cc))])]:
 ks=[];ans=[];english=[];stat=[]
 for i,(aa,bb)in enumerate(pairs):
  a=S.Matrix(aa);c=S.Matrix(bb);dot=S.expand(a.dot(c));rank=S.Matrix.hstack(a,c).rank();label=chr(97+i);stat.append(m(fr'({label})\ a='+v(a)+r',\ b='+v(c)));ks.append(m(fr'({label})\ a\cdot b='+S.latex(dot)))
  k,e=('직교','orthogonal')if dot==0 else('평행','parallel')if rank==1 else('둘 다 아님','neither');ans.append(f'({label}){k}');english.append(f'({label}){e}')
 if n==24:ks.append('c=0이면 두 벡터가 영벡터여서 방향각은 정의되지 않지만 내적0이라는 직교 조건은 성립한다.')
 es=ks[:-1]+['If c=0 both vectors are zero, so their angle is undefined, although their dot product is zero.']if n==24 else ks
 add(n,'직교·평행·그 외로 분류하라: '+'; '.join(stat),'Classify as orthogonal, parallel, or neither: '+'; '.join(stat),ks,es,'; '.join(ans),'; '.join(english),list('abcd')if n==23 else list('abc'),ck='내적0을 먼저 확인하고, 0이 아니면 성분비를 비교했다.',ce='Check zero dot product first, then compare coordinate ratios when it is nonzero.')
add(25,'P=(1,−3,−2),Q=(2,0,−4),R=(6,−2,−5)인 삼각형이 직각인지 벡터로 판정하라.','Use vectors to test whether P=(1,−3,−2),Q=(2,0,−4),R=(6,−2,−5) form a right triangle.',[m(r'QP=\langle-1,-3,2\rangle,\quad QR=\langle4,-2,-1\rangle'),m(r'QP\cdot QR=-4+6-2=0')],[m(r'QP=\langle-1,-3,2\rangle,\quad QR=\langle4,-2,-1\rangle'),m(r'QP\cdot QR=-4+6-2=0')],'Q에서 직각이다.','The right angle is at Q.',ck='세 변의 제곱은14,21,35로14+21=35이다.',ce='The squared side lengths14,21,35 satisfy14+21=35.')
add(26,m(r'\langle2,1,-1\rangle,\langle1,x,0\rangle')+'의 사이각이45°가 되는 x를 구하라.','Find x making the angle between '+m(r'\langle2,1,-1\rangle,\langle1,x,0\rangle')+' equal45°.',[m(r'\frac{x+2}{\sqrt6\sqrt{1+x^2}}=\frac1{\sqrt2},\quad x+2>0'),m(r'(x+2)^2=3(1+x^2)\ \Longrightarrow\ 2x^2-4x-1=0')],[m(r'\frac{x+2}{\sqrt6\sqrt{1+x^2}}=\frac1{\sqrt2},\quad x+2>0'),m(r'(x+2)^2=3(1+x^2)\ \Longrightarrow\ 2x^2-4x-1=0')],m(r'x=1\pm\frac{\sqrt6}{2}'),ck='두 근 모두x+2>0이어서 제곱 전 식도 만족한다.',ce='Both roots satisfyx+2>0 and hence the original unsquared equation.')
add(27,'i+j와i+k에 모두 수직인 단위벡터 하나를 구하라.','Find one unit vector perpendicular to both i+j and i+k.',[m(r'u=\langle a,b,c\rangle:\quad a+b=a+c=0'),m(r'b=c=-a,\quad3a^2=1')],[m(r'u=\langle a,b,c\rangle:\quad a+b=a+c=0'),m(r'b=c=-a,\quad3a^2=1')],m(r'u=\frac1{\sqrt3}\langle1,-1,-1\rangle'),ck='반대 부호의 벡터도 가능한 답이다.',ce='The negative of this vector is another valid answer.')
add(28,m(r'v=\langle3,4\rangle')+'와60°를 이루는 두 단위벡터를 구하라.','Find both unit vectors making60° with '+m(r'v=\langle3,4\rangle')+'.',[m(r'\hat v=\langle3/5,4/5\rangle,\quad n=\langle-4/5,3/5\rangle'),m(r'u_{\pm}=\tfrac12\hat v\pm\tfrac{\sqrt3}{2}n')],[m(r'\hat v=\langle3/5,4/5\rangle,\quad n=\langle-4/5,3/5\rangle'),m(r'u_{\pm}=\tfrac12\hat v\pm\tfrac{\sqrt3}{2}n')],m(r'u_\pm=\left\langle\frac{3\mp4\sqrt3}{10},\frac{4\pm3\sqrt3}{10}\right\rangle'),ck='각 벡터의 길이는1이고 v와의 내적은5/2이다.',ce='Each vector has length1 and dot product5/2 with v.')
for n,stat,a,c in [(29,r'y=4-3x,\ y=3x+2',(1,-3),(1,3)),(30,r'5x-y=8,\ x+3y=15',(1,5),(3,-1))]:
 u=S.Matrix(a);vv=S.Matrix(c);co=S.simplify(abs(u.dot(vv))/(u.norm()*vv.norm()));deg=math.degrees(math.acos(float(co)));add(n,m(stat)+' 두 직선 사이 예각을0.1°까지 구하라.','Find the acute angle between '+m(stat)+' to0.1°.',[m('d_1='+v(a)+r',\ d_2='+v(c)),m(r'\cos\theta=\frac{|d_1\cdot d_2|}{|d_1||d_2|}='+S.latex(co))],[m('d_1='+v(a)+r',\ d_2='+v(c)),m(r'\cos\theta=\frac{|d_1\cdot d_2|}{|d_1||d_2|}='+S.latex(co))],m(fr'\theta\approx{deg:.1f}^\circ'),ck='절댓값을 취하여 두 직선 사이의 예각을 선택했다.',ce='The absolute dot product selects the acute angle between lines.')
add(31,m(r'y=x^2,\ y=x^3')+'의 교점에서 접선 사이 각을0.1°까지 구하라.','Find the tangent angles at intersections of '+m(r'y=x^2,\ y=x^3')+' to0.1°.',[m(r'x^2=x^3\Longrightarrow x=0,1'),'원점에서는 두 접선이 모두수평이다. (1,1)에서 기울기는2,3이다.',m(r'\tan\theta=\left|\frac{3-2}{1+2\cdot3}\right|=1/7')],[m(r'x^2=x^3\Longrightarrow x=0,1'),'At the origin both tangents are horizontal. At(1,1) their slopes are2 and3.',m(r'\tan\theta=\left|\frac{3-2}{1+2\cdot3}\right|=1/7')],m(r'(0,0):0.0^\circ;\quad(1,1):8.1^\circ'),ck='원점에서는 엄밀히 예각이 아니라 각0°의 접촉이다.',ce='At the origin the angle is0°, rather than strictly acute.')
add(32,m(r'y=\sin x,y=\cos x,\ 0\le x\le\pi/2')+'의 교점에서 예각을0.1°까지 구하라.','Find the acute intersection angle of '+m(r'y=\sin x,y=\cos x,\ 0\le x\le\pi/2')+' to0.1°.',[m(r'x=\pi/4,\quad m_1=1/\sqrt2,\quad m_2=-1/\sqrt2'),m(r'\tan\theta=\frac{\sqrt2}{1-1/2}=2\sqrt2')],[m(r'x=\pi/4,\quad m_1=1/\sqrt2,\quad m_2=-1/\sqrt2'),m(r'\tan\theta=\frac{\sqrt2}{1-1/2}=2\sqrt2')],m(r'\theta=\arctan(2\sqrt2)\approx70.5^\circ'),ck='단위 접선의 내적 코사인은1/3이다.',ce='The unit tangent cosine is1/3.')
for n,aa in [(33,(4,1,8)),(34,(-6,2,9)),(35,(3,-1,-2)),(36,(S.Rational(-7,10),S.Rational(12,10),S.Rational(-8,10))), (37,(1,1,1))]:
 a=S.Matrix(aa);cos=a/a.norm();ang=[math.degrees(math.acos(float(q)))for q in cos];statement=m('a='+v(aa))if n!=37 else m(r'a=\langle c,c,c\rangle,\ c>0');add(n,statement+'의 방향코사인과 방향각(0.1°)을 구하라.','Find direction cosines and angles(to0.1°) for '+statement+'.',[m(r'(\cos\alpha,\cos\beta,\cos\gamma)=\frac{a}{|a|}='+v(cos))],[m(r'(\cos\alpha,\cos\beta,\cos\gamma)=\frac{a}{|a|}='+v(cos))],m(r'(\cos\alpha,\cos\beta,\cos\gamma)='+v(cos)+fr',\quad(\alpha,\beta,\gamma)=({ang[0]:.1f}^\circ,{ang[1]:.1f}^\circ,{ang[2]:.1f}^\circ)'),ck='세 방향코사인 제곱의 합은1이다.',ce='The sum of squared direction cosines is1.')
