for n,aa,bb in [(39,(-5,12),(4,6)),(40,(1,4),(2,3)),(41,(4,7,-4),(3,-1,1)),(42,(-1,4,8),(12,1,2)),(43,(3,-3,1),(2,4,-1)),(44,(1,2,3),(5,0,-1))]:
 a=S.Matrix(aa);c=S.Matrix(bb);dot=a.dot(c);comp=dot/a.norm();proj=dot/a.dot(a)*a;add(n,m('a='+v(a)+r',\ b='+v(c))+'에 대해 b의 a방향 스칼라·벡터 정사영을 구하라.','Find the scalar and vector projections of b onto a for '+m('a='+v(a)+r',\ b='+v(c))+'.',[m(r'a\cdot b='+S.latex(dot)+r',\quad |a|^2='+S.latex(a.dot(a))),m(r'\operatorname{comp}_a b=\frac{a\cdot b}{|a|},\quad\operatorname{proj}_a b=\frac{a\cdot b}{|a|^2}a')],[m(r'a\cdot b='+S.latex(dot)+r',\quad |a|^2='+S.latex(a.dot(a))),m(r'\operatorname{comp}_a b=\frac{a\cdot b}{|a|},\quad\operatorname{proj}_a b=\frac{a\cdot b}{|a|^2}a')],m(r'\operatorname{comp}_a b='+S.latex(comp)+r',\quad\operatorname{proj}_a b='+v(proj)),ck='b에서 벡터 정사영을 뺀 나머지와 a의 내적은0이다.',ce='The residual b minus its projection has zero dot product with a.')
